<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;">out    </span><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;"> GoMeta</span><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#6CB6FF;">outputs</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;">(result)           </span><span style="--shiki-light:#4B535D;--shiki-dark:#768390;"># (blsStructure_bytes, render_bytes)</span></span>
